+
+  /// The learned cap for one model identity (null = unknown/none).
+  int? capFor(String provider, String modelId) =>
+      recordFor(provider, modelId)?.maxMessages;
+
+  /// Whether the model is flagged cap-unknown (E1: a refusal without a
