+  Map<String, dynamic> toJson() => {
+    if (maxMessages != null) 'maxMessages': maxMessages,
+    if (capUnknown) 'capUnknown': true,
+  };
+}
+
+/// The learned per-model message-cap store (gh-1680, AC2).
+///
