      final input = [
        _assistantText('old answer one'),
        UserMessage.text('newest'),
      ];
      final out = coalesceMessagesForCap(input, targetMessageCount: 1);
      expect(out.length, lessThanOrEqualTo(1 + 1));
      expect(out.last, same(input.last));
    });
  });
