void main() {
  test('steering interleave: call before newest user, result after', () {
    final call = AssistantMessage(
      content: [ToolCall(id: 'c1', name: 'read', arguments: {})],
      api: 'a', provider: 'p', model: 'm', usage: Usage.zero,
      stopReason: StopReason.stop, timestamp: DateTime.utc(2026),
    );
    final result = ToolResultMessage(
      toolCallId: 'c1', toolName: 'read',
      content: [TextContent(text: 'IMPORTANT TOOL OUTPUT')],
      isError: false, timestamp: DateTime.utc(2026),
    );
    final input = <Message>[
      UserMessage.text('older turn'),
      call,
      UserMessage.text('newest steering message'),
      result,
    ];
    final out = coalesceMessagesForCap(input, targetMessageCount: 2);
    print('OUT (${out.length}):');
    for (final m in out) { print('  ${m.role}: ${m.toJson()}'); }
    print('pairing: ${validateToolPairing(out)}');
  });

  test('no user messages at all, call+result adjacent at end', () {
    final call = AssistantMessage(
      content: [ToolCall(id: 'c1', name: 'read', arguments: {})],
      api: 'a', provider: 'p', model: 'm', usage: Usage.zero,
      stopReason: StopReason.stop, timestamp: DateTime.utc(2026),
    );
    final result = ToolResultMessage(
      toolCallId: 'c1', toolName: 'read',
      content: [TextContent(text: 'OUTPUT')],
      isError: false, timestamp: DateTime.utc(2026),
    );
    final input = <Message>[
      AssistantMessage(content: const [TextContent(text: 'old')], api: 'a', provider: 'p', model: 'm', usage: Usage.zero, stopReason: StopReason.stop, timestamp: DateTime.utc(2026)),
      call,
      result,
    ];
    final out = coalesceMessagesForCap(input, targetMessageCount: 1);
    print('OUT2 (${out.length}):');
    for (final m in out) { print('  ${m.role}: ${m.toJson()}'); }
    print('pairing: ${validateToolPairing(out)}');
  });
}
